/** The gateway schema (schema/schema.graphqls), generated by scripts/schema-generate.sh. */
export const SCHEMA_SDL =
  "# The single GraphQL contract for Sneakers. Both surfaces speak it:\n#   - live: the gqlgen BFF (this gateway) -> vault/audit gRPC\n#   - mock: the same schema executed in-browser over fixtures\n# Shapes mirror the UI mock. Identity is ambient (no-auth dev: the acting user\n# comes from the X-Dev-User header -> request context), so mutations take no\n# explicit actor argument.\n\nenum FieldKind { text multiline password boolean select file sensitive }\nenum PolicyEnforcement { lax strict }\nenum TypeOrigin { system extension custom }\nenum FolderScope { personal group role }\nenum FolderRole { read write delete bulk owner }\nenum SubjectKind { group user everyone }\n# hostKeyNotPinned: an SSH target without host-key pins (the connector doesn't\n# connect); hostKeyMismatch: the host offered a key that isn't pinned;\n# untrustedCertificate: the target answered, but its TLS certificate failed\n# verification, so the credential was never sent.\nenum HeartbeatResult { ok failed unreachable unknown hostKeyNotPinned hostKeyMismatch untrustedCertificate }\nenum RotationState { ok failed degraded rotating unknown }\n\ntype SecretFieldDef {\n  key: String!\n  label: String!\n  kind: FieldKind!\n  options: [String!]\n  defaultValue: String\n  required: Boolean\n  sensitive: Boolean\n  policyId: String\n  policyEnforcement: PolicyEnforcement\n  # Rotation replaces THIS field's value (not hard-coded to \"password\").\n  rotates: Boolean\n  # Extra-sensitive: reveal shows a partial mask + requires a second double-reveal.\n  superSensitive: Boolean\n  # Validation regex (RE2/ECMA-safe); empty/absent = no constraint.\n  pattern: String\n  # Max input length; absent/0 = no cap.\n  maxLength: Int\n}\n\ntype SecretType {\n  id: ID!\n  name: String!\n  fields: [SecretFieldDef!]!\n  heartbeat: Boolean\n  checkout: Boolean\n  origin: TypeOrigin!\n  vendor: String\n  # \"Allowed rotation\": whether this type may be rotated at all.\n  rotation: Boolean\n}\n\ntype Folder {\n  id: ID!\n  name: String!\n  parentId: String\n  scope: FolderScope!\n  ownerUserId: String\n  groupId: String\n  role: String\n  isMasterPersonal: Boolean\n  order: Int\n  # Output-only: secrets in this folder + all descendants (drives the delete UX).\n  subtreeSecretCount: Int\n  # Output-only: RACI owners — user ids.\n  owners: [String!]\n  # whether the current actor may manage/create-under this folder — authoritative, from the vault\n  canManage: Boolean!\n  # Step-up MFA before a reveal in this folder and below. inherit takes the\n  # nearest ancestor's setting, and at the top the global\n  # SecuritySettings.requireMfaForReveal.\n  revealStepUp: StepUpMode!\n}\n\ntype FolderAccessRule {\n  id: ID!\n  folderId: String!\n  subjectKind: SubjectKind!\n  subjectId: String!\n  role: FolderRole!\n}\n\ntype InheritedFolderRule {\n  rule: FolderAccessRule!\n  fromFolderId: String!\n  fromFolderName: String!\n}\n\n# ---- firewall-RACI ruleset ----------------------------------------------------\n# The four governed RACI actions. C = read + reveal secret values; R =\n# manage (create/edit/rotate); A = approve checkout/access requests;\n# I = informed (see the secret exists / metadata, no reveal).\nenum RaciAction { C I A R }\n\n# A folder's step-up-on-reveal override.\nenum StepUpMode { inherit require off }\n# Tri-state grant per action cell: allow, deny, or blank (fall through). own\n# is valid only on the C (read) cell: \"contribute, own reveal\" — combined\n# with an R allow, create/update anywhere R allows, but reveal only a secret\n# this principal created (see Secret.creatorPrincipalId). Saving own on any\n# cell but C is refused.\nenum RaciGrant { allow deny own }\n\n# One grant cell on a RACI rule row. A missing action = blank (fall through).\ntype RaciRuleGrant {\n  action: RaciAction!\n  value: RaciGrant!\n}\n\n# One ordered firewall row on a folder: a subject with a tri-state grant per\n# RACI action. Evaluated top-down the folder chain (target first, then\n# ancestors); first non-blank allow/deny per action wins.\ntype RaciRule {\n  id: ID!\n  folderId: String!\n  order: Int!\n  subjectKind: SubjectKind!\n  # group name or user id; empty for everyone.\n  subjectName: String!\n  # group rules: the directory group id the rule matches on. subjectName is\n  # then the display name only.\n  subjectId: String\n  grants: [RaciRuleGrant!]!\n}\n\n# A folder's own editable ruleset: owners (auto R+A+C, inherit down) + rules.\ntype FolderRuleset {\n  folderId: String!\n  owners: [String!]!\n  rules: [RaciRule!]!\n  # Rules inherited from ancestor folders, read-only, tagged with their source.\n  inherited: [InheritedRaciRule!]!\n  # Owners inherited from ancestor folders, read-only, tagged with their source.\n  inheritedOwners: [InheritedOwner!]!\n}\n\n# An owner inherited from an ancestor folder, tagged with where it came from.\ntype InheritedOwner {\n  userId: String!\n  fromFolderId: String!\n  fromFolderName: String!\n}\n\n# A RACI rule inherited from an ancestor folder, tagged with where it came from.\ntype InheritedRaciRule {\n  rule: RaciRule!\n  fromFolderId: String!\n  fromFolderName: String!\n}\n\n# The effective access a user has on a folder (Resolve over the chain).\ntype FolderAccess {\n  read: Boolean!\n  reveal: Boolean!\n  manage: Boolean!\n  approve: Boolean!\n  informed: Boolean!\n  manageRuleset: Boolean!\n}\n\ninput RaciRuleGrantInput {\n  action: RaciAction!\n  value: RaciGrant!\n}\n\ninput RaciRuleInput {\n  subjectKind: SubjectKind!\n  subjectName: String!\n  # Required for a new group rule: the directory group id. The vault refuses\n  # a group rule without it (GROUP_ID_REQUIRED).\n  subjectId: String\n  grants: [RaciRuleGrantInput!]!\n}\n\n# A secret's own editable ruleset: rules + inherited rules (secrets have no\n# owners of their own; ownership lives on the enclosing folder).\ntype SecretRuleset {\n  secretId: String!\n  rules: [RaciRule!]!\n  # Rules inherited from the enclosing folder chain, read-only, tagged with their source.\n  inherited: [InheritedRaciRule!]!\n}\n\ntype Secret {\n  id: ID!\n  name: String!\n  folderId: String!\n  typeId: String!\n  targetId: String\n  # The principal (human user id or non-human principal id) that created\n  # this secret, set once at creation. Used by an \"own reveal\" folder grant\n  # to decide whether this secret is readable; empty on a secret created\n  # before this field existed.\n  creatorPrincipalId: String\n  # Every attached target, in attach order (#168); targetId above stays the\n  # first/primary entry, kept in sync. updateSecret's targetId still means\n  # \"replace the whole list with just this one\" — attachSecretTarget/\n  # detachSecretTarget add or remove one target without touching the others.\n  targetIds: [String!]!\n  expiresAt: String\n  lastHeartbeatResult: HeartbeatResult\n  # The connector's reason for lastHeartbeatResult, never a value.\n  lastHeartbeatDetail: String\n  verifiedAt: String\n  masked: Boolean\n  viewCount: Int\n  lastAccessedAt: String\n  retired: Boolean!\n  retiredAt: String!\n  lastRotationResult: RotationState\n  rotatedAt: String\n  rotationIntervalDays: Int\n  nextRotationAt: String\n  # Per-secret automation overrides (audited). True = this secret is never\n  # rotated / heartbeat-checked, even if its type supports it.\n  rotationOptOut: Boolean\n  heartbeatOptOut: Boolean\n  # Why heartbeat can't be switched on right now, for a heartbeat-capable type\n  # whose heartbeat isn't running: \"no target\", \"no connection\" or, for an SSH\n  # Key secret, \"no pinned host key\" on the target. Null when heartbeat is\n  # already running, when it's switched off on purpose (heartbeatOptOut), or\n  # when the type isn't heartbeat-capable at all.\n  heartbeatBlockedReason: String\n  # Approval-required: a non-owner needs one owner's approval for each reveal\n  # or use, in the web or through a personal token. Owners are exempt.\n  requireTokenApproval: Boolean\n  # Always-approve: everyone, owners included, needs another owner's or a\n  # designated approver's approval for each reveal or use.\n  alwaysRequireApproval: Boolean\n  # Whether the signed-in user may read the secret. Set by secretsInFolder and\n  # secret, where a user may see a secret they can't read (shown locked, so\n  # they can request access); null elsewhere.\n  canRead: Boolean\n  # The secret's manual place in its folder, 1-based among the folder's\n  # active secrets; 0 for a retired secret. secretsInFolder returns secrets in\n  # this order.\n  position: Int!\n}\n\n# Parsed metadata off an imported/exported certificate (vault-side parse; never\n# includes key material).\ntype CertMeta {\n  subject: String!\n  issuer: String!\n  sans: [String!]!\n  notBefore: String!\n  notAfter: String!\n  serialNumber: String!\n  fingerprintSha256: String!\n  keyAlgorithm: String!\n  keyBits: Int!\n  isCA: Boolean!\n  # whether the stored secret carries the certificate's private key; lets the\n  # UI seed the key-bearing export-disable state from an import/replace response\n  hasPrivateKey: Boolean!\n}\n\n# Result of importCertificate. A single-entry file (PEM/DER/single-cert PKCS12)\n# yields a persisted secret + its parsed meta. A multi-entry container (e.g. a\n# PKCS12/JKS bundle with several cert+key pairs) yields the list of created\n# secret aliases instead, with secret/meta left null — that's a normal result,\n# not an error.\ntype ImportCertificateResult {\n  secret: Secret\n  aliases: [String!]!\n  meta: CertMeta\n}\n\n# A certificate export ready for download: base64-encoded file bytes + the\n# filename/content-type the UI should hand to the browser.\ntype CertExport {\n  fileBase64: String!\n  filename: String!\n  contentType: String!\n}\n\n# One entry in a secret's append-only value history. `fieldKeys` lists the keys\n# present in that version (for the UI) but never any values — an old value is\n# fetched only via the audited revealSecretVersionField.\ntype SecretVersion {\n  versionNo: Int!\n  createdBy: String!\n  # Human-readable label for createdBy, resolved via identity (falls back to id).\n  createdByName: String!\n  createdAt: String!\n  active: Boolean!\n  fieldKeys: [String!]!\n  # The subset of `fieldKeys` whose value changed vs the immediately-prior\n  # version (the oldest version reports all its keys; a removed field counts as\n  # changed). Empty when a version changed no values. Never exposes a value.\n  changedFieldKeys: [String!]!\n  # Set only for a version a type change produced: describes the change itself\n  # (\"Type changed: Password -> Password Account (SSH); added host; fields\n  # carried over: username, password\"), naming any field added, renamed or\n  # dropped by the mapping. Null for every other version, which renders from\n  # changedFieldKeys as before (\"Changed: <field>, <field>\").\n  changeLabel: String\n}\n\n# A folder move in a secret's history, read from the audit trail. The folder\n# ids are empty for a move recorded before the vault kept them.\ntype SecretMove {\n  movedBy: String!\n  # Human-readable label for movedBy, resolved via identity (falls back to id).\n  movedByName: String!\n  movedAt: String!\n  fromFolderId: String!\n  toFolderId: String!\n}\n\n# Dashboard rollup over the current user's readable secrets.\ntype SecretStats {\n  total: Int!\n  expiringSoon: Int!\n  expired: Int!\n  drift: Int!\n}\n\n# A field key/value pair (GraphQL has no map type).\ntype KeyValue {\n  key: String!\n  value: String!\n}\n\n# A generated asymmetric key pair.\ntype KeyPair {\n  privateKey: String!\n  publicKey: String!\n}\ninput KeyValueInput {\n  key: String!\n  value: String!\n}\n\n# One old-key -> new-key rename for a type change, e.g.\n# { from: \"password\", to: \"note\" }.\ninput FieldMappingInput {\n  from: String!\n  to: String!\n}\n\n# What a type change does with a value that has no field under the new type.\n# notes (the default) moves it to the notes field; refuse fails the change\n# naming the keys. Nothing is dropped under either.\nenum UnmappedFieldPolicy { notes refuse }\n\n# Result of changeSecretType: the secret under its new type, the field KEYS now\n# populated (never values), the old field KEYS whose values moved to the notes\n# field (never values), that notes field when any moved, and the label the new\n# version records for the change itself.\ntype TypeChangedSecret {\n  secret: Secret!\n  fieldKeys: [String!]!\n  movedToNotesKeys: [String!]!\n  notesFieldKey: String\n  changeLabel: String\n}\n\nenum SecretTypeChangeOutcome { carried renamed movedToNotes blocked }\n\n# Where one stored non-empty value would go. Keys only, never values.\ntype SecretTypeChangeField {\n  fromKey: String!\n  # The new type's field or the notes field. Null when it's blocked with no\n  # place to go.\n  toKey: String\n  outcome: SecretTypeChangeOutcome!\n  # The refusal reason for this field, when it's blocked.\n  reason: String\n}\n\n# What changeSecretType would do with the same inputs. Nothing is written. A\n# change the rules refuse is a normal answer with allowed false; refusalReason\n# and refusalMessage are what changeSecretType would refuse with.\ntype SecretTypeChangePreview {\n  allowed: Boolean!\n  refusalReason: String\n  refusalMessage: String\n  # One entry per stored non-empty field, in key order, also when refused.\n  fieldChanges: [SecretTypeChangeField!]!\n  # Required fields of the new type that nothing fills yet; ask for them\n  # through fields.\n  missingRequiredKeys: [String!]!\n  # The notes field values would move into, when any would.\n  notesFieldKey: String\n  # When allowed: the keys the new type would hold, and the change label.\n  fieldKeys: [String!]!\n  changeLabel: String\n  # What automation would do. rotation: none or off. heartbeat: none,\n  # scheduled, no_target or opted_out. target: none, kept or detached.\n  rotation: String!\n  heartbeat: String!\n  target: String!\n  fromTargetId: String\n  targetId: String\n}\n\ninput SecretFieldDefInput {\n  key: String!\n  label: String!\n  kind: FieldKind!\n  options: [String!]\n  defaultValue: String\n  required: Boolean\n  sensitive: Boolean\n  policyId: String\n  policyEnforcement: PolicyEnforcement\n  rotates: Boolean\n  superSensitive: Boolean\n  pattern: String\n  maxLength: Int\n}\n\ninput SecretTypeInput {\n  name: String!\n  fields: [SecretFieldDefInput!]!\n  heartbeat: Boolean\n  checkout: Boolean\n  rotation: Boolean\n}\n\ninput UpdateSecretInput {\n  name: String\n  targetId: String\n  expiresAt: String\n  fields: [KeyValueInput!]\n  # Move the secret to another folder. Omit to keep its current folder.\n  folderId: String\n}\n\ntype Connection {\n  id: ID!\n  name: String!\n  protocol: String!\n  port: Int\n  useTls: Boolean\n  # The KDC port for validating a rotated password over Kerberos; 0 means 88.\n  kdcPort: Int\n  description: String\n  # Output-only: number of targets binding to this connection (server-computed).\n  targetCount: Int!\n}\ninput ConnectionInput {\n  id: ID\n  name: String!\n  protocol: String!\n  port: Int\n  useTls: Boolean\n  kdcPort: Int\n  description: String\n}\n\ntype Target {\n  id: ID!\n  name: String!\n  hostname: String!\n  kind: String\n  domain: String\n  realm: String\n  # Alias for connections' default entry; kept for a caller that hasn't moved\n  # to the list.\n  connectionId: String!\n  # The target's connections, in display order, one connector protocol apiece\n  # and exactly one default (the one a session starts on unless the caller\n  # names another). A target saved before this field existed is read back as\n  # a one-item default list built from connectionId.\n  connections: [TargetConnection!]!\n  description: String\n  # Output-only: number of secrets pointing at this target (server-computed).\n  secretCount: Int!\n  # Output-only: empty = shared (admin-owned); set = personal, owned by this user.\n  # Server-assigned from the actor on create; never settable via TargetInput.\n  ownerUserId: String\n  # SSH host keys the broker accepts for this target, one OpenSSH public key\n  # per entry (\"ssh-ed25519 AAAA... comment\"). Empty = not pinned: SSH\n  # sessions to it are refused.\n  sshHostKeys: [String!]!\n}\n# The SSH host key a target offers, read by the SSH broker during the\n# handshake without authenticating. Nothing is pinned by reading it.\ntype TargetHostKeyScan {\n  targetId: ID!\n  # The key's algorithm, e.g. ssh-ed25519.\n  keyType: String!\n  # The key in authorized_keys form, no comment.\n  publicKey: String!\n  # SHA256:<base64>, as ssh-keygen -l prints it. pinTargetHostKey takes\n  # exactly this value.\n  fingerprint: String!\n  # Whether the target already pins this key.\n  pinned: Boolean!\n}\ntype TargetConnection {\n  connectionId: ID!\n  isDefault: Boolean!\n}\ninput TargetConnectionInput {\n  connectionId: ID!\n  isDefault: Boolean!\n}\ninput TargetInput {\n  id: ID\n  name: String!\n  hostname: String!\n  kind: String\n  domain: String\n  realm: String\n  # Legacy alias for the default connection. Required when connections is\n  # omitted or empty; ignored otherwise.\n  connectionId: ID\n  # The target's connections, ordered, with exactly one default. Omit (or\n  # send empty) to save with connectionId alone instead.\n  connections: [TargetConnectionInput!]\n  description: String\n  # The full pin list (site admin only to change). Omit to keep the target's\n  # current pins; [] clears them.\n  sshHostKeys: [String!]\n}\n\nenum PwStartClass { any letter digit symbol }\n\ntype PasswordPolicy {\n  id: ID!\n  name: String!\n  minLength: Int!\n  maxLength: Int\n  requireUpper: Boolean!\n  requireLower: Boolean!\n  requireDigit: Boolean!\n  requireSymbol: Boolean!\n  rotationDays: Int\n  startClass: PwStartClass\n  endLiteral: String\n  excludeChars: String\n  # Output-only usage (server-computed):\n  isDefault: Boolean!\n  byTypeFields: Int!\n  deletable: Boolean!\n}\ninput PasswordPolicyInput {\n  id: ID\n  name: String!\n  minLength: Int!\n  maxLength: Int\n  requireUpper: Boolean!\n  requireLower: Boolean!\n  requireDigit: Boolean!\n  requireSymbol: Boolean!\n  rotationDays: Int\n  startClass: PwStartClass\n  endLiteral: String\n  excludeChars: String\n}\n\ntype SecuritySettings {\n  defaultPasswordPolicyId: String\n  requireMfaForSensitiveCheckout: Boolean!\n  allowApiForSensitive: Boolean!\n  # Days a resolved access request is retained before the daily purge job\n  # deletes it (and its comment thread) from the workflow DB.\n  requestHistoryRetentionDays: Int\n  # Gateway sliding-session lifetime, in seconds. Applied to session create and\n  # each sliding renewal. Unset resolves to 1800 (30m); the gateway clamps the\n  # effective value to [900, 3600] (15m-60m).\n  sessionTtlSeconds: Int\n  # Global default for step-up MFA before a reveal; folders override it.\n  requireMfaForReveal: Boolean!\n  # How recent a second factor must be (MFA_MAX_AGE), in seconds, as this\n  # gateway enforces it: 1800 (30m) when unset, 0 when every sensitive action\n  # asks. Read-only; set where the services run.\n  mfaMaxAgeSeconds: Int!\n  # \"Restrict top-level folders to admins\". Off by default, when anyone signed\n  # in or a personal token can create a folder with no parent. While on, only a\n  # site admin or root can, through createFolder or a token whose owner is one\n  # through the machine API's createFolderForPrincipal. Changing it needs a site\n  # admin, and the vault audits the change.\n  restrictTopLevelFolders: Boolean!\n}\n# Partial update: only the fields provided are changed.\ninput SecuritySettingsInput {\n  defaultPasswordPolicyId: String\n  requireMfaForSensitiveCheckout: Boolean\n  allowApiForSensitive: Boolean\n  requestHistoryRetentionDays: Int\n  sessionTtlSeconds: Int\n  requireMfaForReveal: Boolean\n  restrictTopLevelFolders: Boolean\n}\n\n# A platform user. `roles` are elevated roles on top of the baseline; `isRoot`\n# marks the protected bootstrap super-admin; `subject` is the login subject, the\n# user's Ory Kratos identity id (empty for pre-created local rows not yet adopted).\ntype User {\n  id: ID!\n  name: String!\n  username: String!\n  email: String!\n  roles: [String!]!\n  isRoot: Boolean!\n  subject: String!\n  # Whether the account's email address has been confirmed via an emailed code.\n  # false until then; login/admin are NOT gated on it.\n  emailVerified: Boolean!\n  # A disabled user can't sign in, and every personal token they own stops\n  # working on its next request.\n  disabled: Boolean!\n}\n\nenum ApprovalStatus { pending approved denied }\n\n# What an approval request asks for: secret_access (the default) or folder_move\n# (a shared -> personal folder move needing site-admin approval).\nenum RequestKind { secret_access folder_move secret_move }\n\n# A time-boxed checkout lease (issued by the checkout saga).\ntype Lease {\n  id: ID!\n  secretId: String!\n  userId: String!\n  issuedAt: String!\n  expiresAt: String!\n  returned: Boolean\n}\n\n# A single-use ticket authorizing one interactive SSH session over the\n# sshbroker's WebSocket PTY endpoint.\ntype SshSessionTicket {\n  wsUrl: String!\n  ticket: String!\n  sessionId: ID!\n  expiresInSeconds: Int!\n}\n\n# A message in an access request's discussion thread, so a requester and\n# approver can chat on the request. authorName is resolved to a display name.\ntype ApprovalComment {\n  id: ID!\n  authorUserId: String!\n  authorName: String!\n  body: String!\n  createdAt: String!\n}\n\ntype ApprovalRequest {\n  id: ID!\n  secretId: String!\n  requestedByUserId: String!\n  status: ApprovalStatus!\n  requestedAt: String!\n  reason: String\n  resolvedAt: String\n  resolvedByUserId: String\n  resolvedByUserName: String\n  comments: [ApprovalComment!]!\n  # Request discriminator + folder-move payload. kind=folder_move requests\n  # carry folderId/destParentId + display names and an empty secretId.\n  kind: RequestKind!\n  folderId: String!\n  destParentId: String!\n  folderName: String!\n  destParentName: String!\n}\n\ntype Group {\n  id: ID!\n  name: String!\n}\n\n# A user-search result label (id + display name), used to resolve subject ids\n# on RACI rule rows back into human-readable names.\ntype UserLabel {\n  id: String!\n  name: String!\n}\n\n# The effective RACI decision for a simulated actor against a folder/secret's\n# chain, evaluated with a draft ruleset that hasn't been saved yet. Each action\n# carries a human-readable reason (which rule/inheritance/ownership decided it).\ntype RaciDecision {\n  read: Boolean!\n  readReason: String!\n  reveal: Boolean!\n  revealReason: String!\n  manage: Boolean!\n  manageReason: String!\n  approve: Boolean!\n  approveReason: String!\n  informed: Boolean!\n  informedReason: String!\n}\n\ntype Notification {\n  id: ID!\n  action: String!\n  resourceKind: String!\n  resourceId: ID!\n  resourceLabel: String!\n  actorLabel: String!\n  occurredAt: String!\n  read: Boolean!\n}\n\n# A single key/value attribute on an audit record (GraphQL has no map type).\ntype AuditAttr {\n  key: String!\n  value: String!\n}\n\n# One record in the append-only, hash-chained audit trail. `tier` is a\n# lowercase string (\"audit\" | \"activity\"); prevHash/hash carry the tamper-\n# evident chain (prevHash is empty for seq 1).\ntype AuditRecord {\n  seq: Int!\n  tier: String!\n  action: String!\n  actorUserId: String!\n  # Human-readable actor label resolved via identity (falls back to the id).\n  actorName: String!\n  subject: String!\n  # The subject's record kind (\"secret\" | \"folder\" | \"target\" | \"user\" |\n  # \"service_account\" | \"unknown\"), resolved from the subject string's id\n  # prefix. subjectId is the same id as subject, broken out so the caller\n  # doesn't have to parse it.\n  subjectKind: String!\n  subjectId: String!\n  # Resolved server-side, batched per page, and access-aware: null when the\n  # caller can't read the subject, or it's deleted, unknown, or unresolved.\n  subjectName: String\n  groupId: String!\n  sensitive: Boolean!\n  attributes: [AuditAttr!]!\n  occurredAt: String!\n  prevHash: String!\n  hash: String!\n}\n\n# The result of verifying the audit hash-chain. `brokenAtSeq` is the first bad\n# record when invalid, 0 when valid.\ntype AuditChainStatus {\n  valid: Boolean!\n  brokenAtSeq: Int!\n  length: Int!\n}\n\n# A non-human principal (external caller, agent, or automation) that\n# authenticates to the machine /machine/graphql endpoint with an opaque Bearer\n# API token instead of a session cookie. Managed here, on the human admin\n# surface: site-admin-gated create/list/disable. Disable is a soft-disable\n# (no delete) — tokens already minted keep their own independent\n# expiry/revocation state.\ntype ServiceAccount {\n  id: ID!\n  name: String!\n  description: String!\n  disabled: Boolean!\n  createdBy: String!\n  createdAtUnix: Int!\n  # OIDC linkage: set once an admin links this service account\n  # to a Hydra OAuth2 client via linkOidcClient, null/absent for the (common)\n  # unlinked case. Surfacing these is what makes an OIDC link observable —\n  # without them there is no way to see which service accounts are\n  # OIDC-linked or to what.\n  oidcIssuer: String\n  oidcSubject: String\n  # Admin-set bound on the OIDC linkage (trust model): the only\n  # RACI groups the linked client may ever hold. At /machine/graphql its\n  # effective groups are its JWT scope groups INTERSECT this list. Empty\n  # (always, for an unlinked account) means NO groups, never \"all\".\n  oidcAllowedGroups: [String!]!\n}\n\n# Metadata about a minted API token — deliberately NEVER the token value\n# itself. The plaintext token is only ever returned once, at mint time, via\n# MintApiTokenResult. revokedAtUnix/lastUsedAtUnix are 0 when unset.\n# A request to use a secret field: by a personal token for one exact command\n# or a reveal to the token, or by a person for a reveal in the web. Approving\n# releases the value once, to whoever prepared it.\ntype SecretUse {\n  id: ID!\n  secretName: String!\n  fieldKey: String!\n  argv: [String!]!\n  clientLabel: String!\n  state: String!\n  expiresAtUnix: Int!\n  # The value goes to the token itself, not to a command; argv is empty.\n  reveal: Boolean!\n  # Groups the uses one agent run raised. A display hint from the agent, never an authority.\n  runId: ID\n  # The agent's own words for its task, empty when it gave none. Show it as plain text.\n  purpose: String!\n  # The token's name, or the client label when the name can't be found.\n  requester: String!\n  # The person who asked, by display name (their user id when it can't be found).\n  requestedBy: String!\n  # Nobody else can decide this use: the person who asked confirms it once\n  # with a second factor (confirmSecretUses) instead of waiting.\n  confirm: Boolean!\n}\n\n# The caller's own pending, unexpired uses with one run id.\ntype SecretUseRun {\n  runId: ID!\n  uses: [SecretUse!]!\n  # When the session's second factor stops covering an approval; 0 when it doesn't now.\n  mfaFreshUntilUnix: Int!\n}\n\nenum SecretUseDecision {\n  APPROVE\n  DENY\n}\n\n# Why one use in a batch wasn't decided.\nenum SecretUseRefusal {\n  EXPIRED\n  ALREADY_DECIDED\n  NOT_FOUND\n  NOT_PERMITTED\n  UNAVAILABLE\n  # You asked for this use yourself; another owner or approver decides it.\n  SELF_APPROVAL\n  # Someone else can decide this use, so it can't be confirmed by its requester.\n  OTHER_APPROVER\n  # Nobody can approve this use.\n  NO_APPROVER\n}\n\ntype SecretUseOutcome {\n  id: ID!\n  decided: Boolean!\n  # Set when decided.\n  use: SecretUse\n  # Set when refused.\n  reason: SecretUseRefusal\n}\n\ntype DecideSecretUsesResult {\n  # One per distinct id, in request order.\n  outcomes: [SecretUseOutcome!]!\n}\n\ntype UseGrantProgram {\n  program: String!\n  argPattern: String!\n}\n\n# A bounded pre-approval: uses by one token inside this scope need no per-use approval.\ntype UseGrant {\n  id: ID!\n  tokenId: ID!\n  secretIds: [ID!]!\n  folderId: ID\n  fieldKeys: [String!]!\n  programs: [UseGrantProgram!]!\n  expiresAtUnix: Int!\n  maxUses: Int!\n  uses: Int!\n  revokedAtUnix: Int!\n  # Also covers reveals to the token, for secrets that require token approval.\n  allowReveal: Boolean!\n}\n\ninput UseGrantProgramInput {\n  program: String!\n  argPattern: String!\n}\n\ninput UseGrantInput {\n  tokenId: ID!\n  secretIds: [ID!]\n  folderId: ID\n  fieldKeys: [String!]\n  programs: [UseGrantProgramInput!]!\n  expiresAtUnix: Int!\n  maxUses: Int\n  allowReveal: Boolean\n}\n\n# A fresh second-factor proof: kind totp or email with code, or passkey with\n# credentialJson and webauthnSessionId from beginMfaPasskey.\ninput FactorInput {\n  kind: String!\n  code: String\n  credentialJson: String\n  webauthnSessionId: String\n}\n\ntype PasskeyChallenge {\n  options: String!\n  webauthnSessionId: String!\n}\n\n# A personal token owned by one user. It identifies the user only; permissions\n# are resolved live on every request. The token value is never returned here.\ntype UserToken {\n  id: ID!\n  label: String!\n  clientName: String!\n  createdAtUnix: Int!\n  lastUsedAtUnix: Int!\n  expiresAtUnix: Int!\n  revokedAtUnix: Int!\n}\n\ntype ApiToken {\n  id: ID!\n  serviceAccountId: ID!\n  scope: String!\n  expiresAtUnix: Int!\n  revokedAtUnix: Int!\n  lastUsedAtUnix: Int!\n  createdBy: String!\n}\n\n# The one-time result of minting an API token: the plaintext token (shown to\n# the admin exactly once — never logged, never re-fetchable) plus the newly\n# minted token's metadata.\ntype MintApiTokenResult {\n  token: String!\n  apiToken: ApiToken!\n}\n\n# A break-glass browse session: a short-lived window a site admin opens with a\n# reason and an MFA code, in which every folder and secret is listed. It grants\n# no edit or manage rights. openedAt is the \"entered\" event and endedAt with\n# endReason the \"left\" one; reveals lists every secret revealed in it.\ntype BreakGlassSession {\n  id: ID!\n  actorUserId: String!\n  # The actor's display label (the raw id when identity can't resolve it).\n  actorName: String!\n  reason: String!\n  # RFC3339, UTC.\n  openedAt: String!\n  expiresAt: String!\n  # Null while the session is open.\n  endedAt: String\n  # \"exit\", \"expired\" or \"replaced\"; null while open.\n  endReason: String\n  # Filled by breakGlassSessions only; empty elsewhere.\n  reveals: [BreakGlassReveal!]!\n}\n\n# One secret revealed in a break-glass session. Never a value.\ntype BreakGlassReveal {\n  eventId: ID!\n  secretId: ID!\n  # The secret's current name; empty once the secret is gone.\n  secretName: String!\n  revealedAt: String!\n  postRotationScheduled: Boolean!\n  ownerNotified: Boolean!\n}\n\n# Everything a break-glass session lists: every folder (personal ones\n# included) and every live secret, as metadata only.\ntype BreakGlassBrowse {\n  folders: [Folder!]!\n  secrets: [Secret!]!\n}\n\ntype Query {\n  users: [User!]!\n  # A single user by id (identity directory), for the admin user-detail surface.\n  user(id: String!): User\n  groups: [Group!]!\n  # Directory groups a user is a direct member of.\n  userGroups(userId: String!): [Group!]!\n  # Users who are direct members of a group.\n  groupMembers(groupId: String!): [User!]!\n  # Retired: always empty. Group membership is managed only in Sneakers.\n  userAdGroups(userId: String!): [String!]!\n  # Typeahead search over users, for picking RACI subjects / simulator actors.\n  searchUsers(query: String!, limit: Int): [User!]!\n  # Resolves a batch of user ids to display labels (id + name).\n  resolveUserLabels(ids: [String!]!): [UserLabel!]!\n  # Previews the effective RACI decision for userId on a folder if draftRules\n  # (not yet saved) were in effect, without persisting anything.\n  simulateFolder(folderId: String!, userId: String!, draftRules: [RaciRuleInput!]!): RaciDecision!\n  # Previews the effective RACI decision for userId on a secret if draftRules\n  # (not yet saved) were in effect, without persisting anything.\n  simulateSecret(secretId: String!, userId: String!, draftRules: [RaciRuleInput!]!): RaciDecision!\n  activeLeasesForUser(userId: String!): [Lease!]!\n  activeLease(secretId: String!): Lease\n  approvalRequests: [ApprovalRequest!]!\n  connections: [Connection!]!\n  targets: [Target!]!\n  # Reads the SSH host key the target's SSH connection offers, for a person to\n  # check before pinning it with pinTargetHostKey. Site admins only (the same\n  # people who may change a target's pins); the broker rate-limits scans per\n  # user. Audited by the broker as hostkey.scan.\n  scanTargetHostKey(targetId: ID!): TargetHostKeyScan!\n  passwordPolicies: [PasswordPolicy!]!\n  securitySettings: SecuritySettings!\n  secretTypes: [SecretType!]!\n  # What changeSecretType would do with these inputs, without writing anything.\n  # Same access as the change; returns keys, never values.\n  previewSecretTypeChange(id: ID!, newTypeId: ID!, fieldMapping: [FieldMappingInput!], fields: [KeyValueInput!], unmappedFields: UnmappedFieldPolicy): SecretTypeChangePreview!\n  # Extension packs available to install (not yet installed).\n  availableExtensions: [SecretType!]!\n  folders: [Folder!]!\n  # Break-glass (site admin or root, web sessions only). The caller's open\n  # session for this web session, or null; null for anyone else.\n  breakGlassSession: BreakGlassSession\n  # Every folder and live secret while the session is open; folderId narrows\n  # the secrets. Refused with BREAK_GLASS_SESSION_CLOSED once it has ended.\n  breakGlassBrowse(sessionId: ID!, folderId: ID): BreakGlassBrowse!\n  # Break-glass sessions, newest first, each with the secrets revealed in it,\n  # for the audit log. limit defaults to 50, at most 200.\n  breakGlassSessions(limit: Int): [BreakGlassSession!]!\n  secretsInFolder(folderId: String!, includeRetired: Boolean): [Secret!]!\n  # Every secret attached to a target (#168), for the target's own page.\n  # Same visibility as secretsInFolder: a secret the caller can see but not\n  # read is included locked (canRead false); one an explicit deny covers is\n  # omitted.\n  secretsByTarget(targetId: ID!): [Secret!]!\n  secret(id: ID!): Secret\n  secretStats: SecretStats!\n  topAccessedSecrets(limit: Int): [Secret!]!\n  # Dashboard drill-down: the caller's readable secrets filtered by a stat tile's\n  # status. status ∈ \"expiring\" | \"expired\" | \"drift\" | \"all\".\n  secretsByStatus(status: String!): [Secret!]!\n  findSecretsByPublicKey(query: String!): [Secret!]!\n  # Non-sensitive field values only (sensitive values require revealSecretField).\n  secretFields(id: ID!): [KeyValue!]!\n  # A secret's value history (newest version first). Metadata + field keys only;\n  # gated by the same read access as revealing the secret.\n  secretVersions(secretId: ID!): [SecretVersion!]!\n  # A secret's folder moves, newest first. Gated by the same access as\n  # secretVersions.\n  secretMoves(secretId: ID!): [SecretMove!]!\n  folderRules(folderId: String!): [FolderAccessRule!]!\n  inheritedFolderRules(folderId: String!): [InheritedFolderRule!]!\n  # A folder's firewall-RACI ruleset (owners + own rules + inherited rules).\n  folderRuleset(folderId: String!): FolderRuleset!\n  # The acting user's effective RACI access on a folder (Resolve over the chain).\n  myFolderAccess(folderId: String!): FolderAccess!\n  # A secret's own firewall-RACI ruleset (own rules + inherited rules).\n  secretRuleset(secretId: String!): SecretRuleset!\n  # The acting user's effective RACI access on a secret (Resolve over the chain).\n  mySecretAccess(secretId: String!): FolderAccess!\n  # The acting user's Informed-notification inbox, newest first.\n  myNotifications(limit: Int): [Notification!]!\n  # The acting user's unread notification count (for the header badge).\n  myUnreadNotificationCount: Int!\n  # The audit trail (admin-only): optional filters by actor and/or subject, with\n  # an optional limit (0/omitted = no limit). `excludeActions` drops records whose\n  # action is in the set BEFORE the limit, so exclusion spans the whole chain (not\n  # just the fetched window). Newest-first per the audit service.\n  auditRecords(actorUserId: String, subject: String, excludeActions: [String!], limit: Int): [AuditRecord!]!\n  # The full set of distinct action strings present in the chain (admin-only), so\n  # the UI can offer the complete \"hide actions\" list rather than only the actions\n  # in the fetched window.\n  auditActions: [String!]!\n  # Verifies the audit hash-chain (admin-only) for the tamper-evidence banner.\n  auditChain: AuditChainStatus!\n\n  # Site-admin-only: the service-account principals provisioned for machine\n  # access.\n  serviceAccounts: [ServiceAccount!]!\n  # Site-admin-only: a service account's minted API tokens (metadata only —\n  # never the token value; see MintApiTokenResult for the one-time reveal).\n  apiTokens(serviceAccountId: ID!): [ApiToken!]!\n  # The caller's own personal tokens.\n  myTokens: [UserToken!]!\n  # Your own pending uses (your tokens' and your web reveals), waiting for an\n  # owner or approver, or for your confirmation.\n  pendingSecretUses: [SecretUse!]!\n  # Other people's pending uses you may decide, as an owner of the secret or\n  # (for an always-approve secret) a designated approver. Never your own.\n  secretUsesToDecide: [SecretUse!]!\n  # Your pending uses from one agent run.\n  secretUseRun(runId: ID!): SecretUseRun!\n  # Your use grants.\n  useGrants: [UseGrant!]!\n  # Site-admin: another user's personal tokens.\n  userTokens(userId: String!): [UserToken!]!\n  # Build and version facts for a support report: the caller, the gateway,\n  # every Sneakers-PAM service and the third-party services the gateway can\n  # reach. Any signed-in user; no arguments, so the actor is always the\n  # caller. Cached for about 30 seconds. Never carries tokens, secrets,\n  # addresses or error text.\n  diagnostics: Diagnostics!\n  # Whether the install is in read-only maintenance, for the banner. While\n  # it's on, mutations are refused with the reason MAINTENANCE_READONLY;\n  # reads, reveals and sign-in still work.\n  maintenance: Maintenance!\n  # The appliance's state, from its sneakers-appliance ConfigMap, for the\n  # web banners. present is false on a plain Kubernetes install, and every\n  # other field is then null or false.\n  appliance: Appliance!\n}\n\ntype Appliance {\n  present: Boolean!\n  # The appliance version.\n  version: String\n  # starting, ok, degraded, down, maintenance or stopped.\n  productState: String\n  # The MCP: on, off or degraded.\n  mcp: String\n  # The MCP is off but revoking its agent tokens hasn't finished.\n  mcpRevokePending: Boolean!\n  # The machine API: on or off.\n  machineApi: String\n  # How the product certificate was set: self-signed, upload, csr or acme.\n  tlsMode: String\n  # When the product certificate expires (RFC 3339).\n  tlsNotAfter: String\n  maintenance: Boolean!\n  maintenanceReason: String\n}\n\ntype Maintenance {\n  readOnly: Boolean!\n  # Why, when the appliance gave a reason; null otherwise.\n  reason: String\n}\n\ntype Diagnostics {\n  # When the component versions were read (RFC 3339, UTC); they're cached, so\n  # this can be up to 30 seconds old.\n  generatedAt: String!\n  # This read's own trace id.\n  traceId: String!\n  actor: DiagnosticsActor!\n  # The origin of the configured public URL (scheme and host only).\n  publicUrl: String!\n  # The product release this install runs; null when the install doesn't\n  # say (SNEAKERS_PRODUCT_VERSION).\n  productVersion: String\n  # The appliance's Base OS version; null when not running on the\n  # appliance. box carries it with the rest of the box's values.\n  appliance: String\n  # The appliance the product runs on; null when not running on one.\n  box: DiagnosticsBox\n  gateway: ComponentVersion!\n  # identity, vault, workflow, audit, notify, sshbroker, mcp, and one\n  # \"connector\" entry per connector worker vault has heard from.\n  services: [ComponentVersion!]!\n  # kratos, hydra, polis, valkey, postgres, rabbitmq and kubernetes.\n  thirdParty: [ComponentVersion!]!\n}\n\n# The appliance as the box gives it to the product. Each value is\n# \"unknown\" when the box didn't give it.\ntype DiagnosticsBox {\n  # The Base OS version.\n  baseOS: String!\n  # The Base Web version: the box's own admin pages.\n  baseWeb: String!\n  # The box's fully qualified host name (or its address).\n  fqdn: String!\n}\n\n# The caller, as identity knows them.\ntype DiagnosticsActor {\n  id: String!\n  username: String!\n  roles: [String!]!\n}\n\ntype ComponentVersion {\n  name: String!\n  # Null when it couldn't be read; \"unknown\" when the component answered\n  # without one.\n  version: String\n  commit: String\n  status: ComponentStatus!\n  # The component's readiness by dependency, as its health check reports it;\n  # null when it doesn't report one (an older build, or a third-party\n  # service).\n  dependencies: [DependencyState!]\n  # When this component last verifiably called in (RFC 3339, UTC); null when\n  # it doesn't report one. Set on the connector entries only.\n  lastContactAt: String\n}\n\ntype DependencyState {\n  # A dependency name such as postgres, valkey, kratos or audit.\n  name: String!\n  state: DependencyHealth!\n  # Whether the component's readiness fails while this is down.\n  required: Boolean!\n  # When it isn't OK: timeout, refused, unavailable, unauthenticated or error,\n  # or go-buildinfo's connection-refused, dns, network, canceled or panic.\n  error: String\n  version: String\n}\n\nenum DependencyHealth {\n  OK\n  # An optional dependency is failing; the component still serves.\n  DEGRADED\n  # A required dependency is failing; the component isn't ready.\n  DOWN\n}\n\nenum ComponentStatus {\n  OK\n  # Configured, but it didn't answer.\n  UNAVAILABLE\n  # Not part of this deployment.\n  NOT_CONFIGURED\n}\n\ninput CreateSecretInput {\n  name: String!\n  folderId: String!\n  typeId: String!\n  targetId: String\n  expiresAt: String\n  fields: [KeyValueInput!]!\n}\n\ntype Mutation {\n  saveConnection(input: ConnectionInput!): Connection!\n  deleteConnection(id: ID!): Boolean!\n  saveTarget(input: TargetInput!): Target!\n  deleteTarget(id: ID!): Boolean!\n  # Pins the host key the target offers now, only when its fingerprint is\n  # exactly the one given (the one the person saw from scanTargetHostKey).\n  # A different key is refused with HOST_KEY_CHANGED and nothing is pinned.\n  # Site admins only. Adds to the target's existing pins.\n  pinTargetHostKey(targetId: ID!, fingerprint: String!): Target!\n\n  savePasswordPolicy(input: PasswordPolicyInput!): PasswordPolicy!\n  deletePasswordPolicy(id: ID!): Boolean!\n  updateSecuritySettings(input: SecuritySettingsInput!): SecuritySettings!\n\n  createSecretType(input: SecretTypeInput!): SecretType!\n  updateSecretType(id: ID!, input: SecretTypeInput!): SecretType!\n  deleteSecretType(id: ID!): Boolean!\n  cloneSecretType(id: ID!): SecretType!\n  importExtension(id: ID!): SecretType!\n  importExtensionFromJson(json: String!): SecretType!\n\n  createSecret(input: CreateSecretInput!): Secret!\n  updateSecret(id: ID!, input: UpdateSecretInput!): Secret!\n  # Changes a secret's type as a new version. Needs Author on the secret or\n  # ownership of its folder; a person only, and never drops a stored value.\n  changeSecretType(id: ID!, newTypeId: ID!, fieldMapping: [FieldMappingInput!], fields: [KeyValueInput!], unmappedFields: UnmappedFieldPolicy): TypeChangedSecret!\n  # Attach/detach one target on a secret's list, never touching the others\n  # (#168) — unlike updateSecret's targetId, which replaces the whole list\n  # with just the one it names.\n  attachSecretTarget(secretId: ID!, targetId: ID!): Secret!\n  detachSecretTarget(secretId: ID!, targetId: ID!): Secret!\n  # Reveals ONE sensitive field; audited + RBAC-gated server-side.\n  revealSecretField(id: ID!, fieldKey: String!): String!\n  # Reveals ONE field from a prior version; audited + RBAC-gated server-side.\n  # Prior values are the recovery view: the vault needs the recovery role and a\n  # fresh MFA (RECOVERY_ROLE_REQUIRED, STEP_UP_REQUIRED) and audits each one.\n  revealSecretVersionField(secretId: ID!, versionNo: Int!, fieldKey: String!): String!\n  # Make a prior version's fields the current ones, as a new version. Recovery\n  # role and a fresh MFA; refused while the secret is checked out or rotating.\n  restoreSecretVersion(secretId: ID!, versionNo: Int!): Secret!\n  # Emergency access: bypasses checkout-lock/approval-pending for a\n  # read-eligible actor. Requires a fresh TOTP code (MFA step-up); high-severity\n  # audit, owner notify, and forced post-use rotation are triggered server-side.\n  # sessionId makes it a reveal inside a break-glass browse session: the\n  # session id is recorded with the reveal, and an empty reason takes the\n  # session's.\n  breakGlassSecret(secretId: String!, reason: String!, code: String!, sessionId: ID): [KeyValue!]!\n  # Opens a break-glass browse session (site admin or root, web sessions only)\n  # with a reason and a fresh TOTP code, under the same step-up rules as\n  # breakGlassSecret. Any session the caller has open ends as replaced.\n  openBreakGlassSession(reason: String!, code: String!): BreakGlassSession!\n  # Ends the caller's break-glass session. Stays open in read-only maintenance.\n  closeBreakGlassSession(id: ID!): BreakGlassSession!\n  # Copies the primary sensitive field value (distinct audited \"copy\" event).\n  copySecret(id: ID!): String\n  # Soft-delete: hides the secret from default listings, recoverable via restoreSecret.\n  retireSecret(id: String!): Secret!\n  # Reverses retireSecret.\n  restoreSecret(id: String!): Secret!\n  # Hard delete: permanently removes the secret. Irreversible.\n  deleteSecret(id: String!): Boolean!\n\n  # Imports a certificate file (PEM/DER/PKCS12/PKCS7/JKS) into folderId as a new\n  # secret named `name`. passphrase decrypts an encrypted container/key;\n  # alias picks one entry out of a multi-entry container. A multi-entry\n  # container with no alias given returns the list of created aliases instead\n  # of a single secret (see ImportCertificateResult).\n  importCertificate(folderId: String!, name: String!, fileBase64: String!, passphrase: String, alias: String): ImportCertificateResult!\n  # Exports an existing certificate secret in the given format\n  # (pkcs12|pem|pem-cert|pem-key|pem-fullchain|der|pkcs7|jks). newPassphrase\n  # re-encrypts the exported container/key where the format supports it.\n  exportCertificate(secretId: String!, format: String!, newPassphrase: String): CertExport!\n  # Replaces an existing certificate secret's material in place with a freshly\n  # issued certificate file (e.g. after a CA re-issue) without changing the\n  # secret's id, folder, or ruleset; appends a new version to the secret's\n  # ledger. passphrase and alias behave as in importCertificate. A multi-entry\n  # container with no alias given returns the list of created aliases instead\n  # of a single secret (see ImportCertificateResult).\n  replaceCertificate(secretId: String!, fileBase64: String!, passphrase: String, alias: String): ImportCertificateResult!\n  # Generates a new asymmetric key pair in the given format (e.g. rsa2048|rsa4096|ec256|ec384).\n  generateKeyPair(format: String!): KeyPair!\n\n  # With no parentId, a shared top-level folder. Open to anyone unless the\n  # restrictTopLevelFolders security setting is on; then the vault refuses\n  # anyone but a site admin or root with PERMISSION_DENIED\n  # (TOP_LEVEL_FOLDERS_RESTRICTED).\n  createFolder(parentId: String, name: String!): Folder!\n  renameFolder(id: ID!, name: String!): Folder!\n  moveFolder(id: ID!, newParentId: String): Folder!\n  # reassignToId optional: omit to delete an empty-of-secrets folder (cascades empty children).\n  deleteFolder(id: ID!, reassignToId: String): Boolean!\n  reorderFolders(parentId: String, orderedIds: [String!]!): Boolean!\n  # Sets the manual order of a folder's active secrets. orderedIds must name\n  # every active secret in the folder exactly once. Needs RACI Author on the\n  # folder or folder ownership. Returns the folder's secrets in the new order.\n  reorderSecrets(folderId: ID!, orderedIds: [ID!]!): [Secret!]!\n\n  addFolderRule(folderId: String!, subjectKind: SubjectKind!, subjectId: String!, role: FolderRole!): FolderAccessRule!\n  removeFolderRule(id: ID!): Boolean!\n\n  # Replace a folder's entire firewall-RACI ruleset (owners + ordered rules).\n  setFolderRuleset(folderId: String!, owners: [String!]!, rules: [RaciRuleInput!]!): FolderRuleset!\n  # Set a folder's step-up-on-reveal override. Human site admin only (the\n  # vault decides).\n  setFolderRevealStepUp(folderId: String!, mode: StepUpMode!): Folder!\n  # Replace a secret's entire firewall-RACI ruleset (ordered rules).\n  setSecretRuleset(secretId: String!, rules: [RaciRuleInput!]!): SecretRuleset!\n\n  # Access workflow (go-saga): checkout drives the checkout saga.\n  checkoutSecret(secretId: String!, hours: Int): Lease!\n  checkinSecret(secretId: String!): Boolean!\n  createAccessRequest(secretId: String!, reason: String): ApprovalRequest!\n  # Request a shared -> personal folder move for site-admin approval. Used\n  # when a non-admin drags shared content into a personal folder; destParentId\n  # may be any user's personal folder.\n  createFolderMoveRequest(folderId: String!, destParentId: String!, reason: String, folderName: String, destParentName: String): ApprovalRequest!\n  # Request a shared -> personal SECRET move for site-admin approval.\n  createSecretMoveRequest(secretId: String!, destFolderId: String!, reason: String, secretName: String, destFolderName: String): ApprovalRequest!\n  resolveApproval(id: ID!, approve: Boolean!, grantHours: Int): ApprovalRequest!\n  # Adds a message to an access request's discussion thread.\n  addApprovalComment(requestId: String!, body: String!): ApprovalRequest!\n\n  # Triggers an agentless credential rotation for the secret.\n  rotateSecret(secretId: String!): Boolean!\n\n  # Per-secret automation override (audited): disable/enable rotation and/or\n  # heartbeat for this specific secret. Returns the updated secret.\n  setSecretAutomation(secretId: String!, disableRotation: Boolean!, disableHeartbeat: Boolean!): Secret!\n  # Manage rights on the secret; a signed-in person only.\n  # required alone is approval-required; with always it is always-approve;\n  # required false turns both off.\n  setSecretTokenApproval(secretId: String!, required: Boolean!, always: Boolean): Secret!\n\n  # Group membership (identity is the source of truth). Admin-gated server-side\n  # (acting user must be a site-admin or root). Idempotent; returns true on success.\n  addGroupMember(userId: String!, groupId: String!): Boolean!\n  removeGroupMember(userId: String!, groupId: String!): Boolean!\n\n  # Create a directory group. Admin-gated server-side (acting user must be\n  # site-admin or root). Returns the new group.\n  createGroup(name: String!): Group!\n\n  # Create a local user account, backed by an Ory Kratos identity. Admin-gated\n  # server-side (acting user must be site-admin or root). The password is\n  # admin-supplied (typically client-generated); the user then signs in through\n  # Ory Kratos. Roles are assigned separately.\n  createLocalUser(username: String!, email: String!, name: String!, password: String!): User!\n\n  # Email verification: confirm an account's email/username spelling.\n  # requestEmailVerification (re)sends a verification code; admin-gated\n  # server-side. confirmEmailVerification verifies the emailed code (keyed by\n  # userId or email) and marks the account verified; it returns false for a\n  # wrong/expired code and never reveals whether the account exists. The\n  # unauthenticated /setup and pre-login flows use the public REST\n  # /auth/verify/* endpoints (this confirm mutation is for authed contexts).\n  requestEmailVerification(userId: String!): Boolean!\n  confirmEmailVerification(userId: String, email: String, code: String!): Boolean!\n\n  # Replace a user's role set — grant/revoke e.g. the \"admin\" role. Admin-gated\n  # server-side. root's admin authority is is_root-derived and unaffected.\n  setUserRoles(userId: String!, roles: [String!]!): User!\n  # Site-admin: disable or re-enable a user. Refused for the caller's own account.\n  setUserDisabled(userId: String!, disabled: Boolean!): User!\n  revokeMyToken(id: ID!): UserToken!\n  # Delete one of your own revoked tokens. Identity refuses an active token with\n  # FAILED_PRECONDITION and answers NOT_FOUND for any token that isn't yours.\n  deleteMyToken(id: ID!): Boolean!\n  # Decide someone else's pending use as an owner or approver. Approving needs\n  # a session factor within MFA_MAX_AGE or a factor here; denying does not.\n  # You may deny (withdraw) your own use but never approve it.\n  decideSecretUse(id: ID!, approve: Boolean!, factor: FactorInput): SecretUse!\n  # Decide 1 to 20 pending uses at once, each through the single-use path with\n  # its own checks and audit. APPROVE needs a session factor within\n  # MFA_MAX_AGE or a factor here, checked once; DENY needs neither. A refused\n  # item doesn't stop the others.\n  decideSecretUses(ids: [ID!]!, decision: SecretUseDecision!, factor: FactorInput): DecideSecretUsesResult!\n  # Confirm 1 to 20 of your own pending uses that nobody else can decide\n  # (confirm: true), once for the whole task: a session factor within\n  # MFA_MAX_AGE or a factor here, checked once.\n  confirmSecretUses(ids: [ID!]!, factor: FactorInput): DecideSecretUsesResult!\n  # Ask to reveal a field of a secret whose approval level needs a decision\n  # (revealSecretField answered APPROVAL_REQUIRED). runId groups one task's\n  # reveals on one page. The use waits for an owner or approver, or for your\n  # confirmation when confirm is true.\n  prepareSecretReveal(secretId: ID!, fieldKey: String!, runId: ID): SecretUse!\n  # Release the value of your approved reveal use, once. The step-up window\n  # still applies.\n  redeemSecretReveal(id: ID!): String!\n  # Creating a grant needs a fresh second factor and one of your own tokens.\n  createUseGrant(input: UseGrantInput!, factor: FactorInput!): UseGrant!\n  revokeUseGrant(id: ID!): UseGrant!\n  # Email a one-time code for a factor check.\n  sendMfaEmailCode: Boolean!\n  # Start a passkey factor check.\n  beginMfaPasskey: PasskeyChallenge!\n  # Site-admin: revoke another user's personal token.\n  revokeUserToken(userId: String!, id: ID!): UserToken!\n\n  # Edit a user's profile — display name, email, and username. Admin-gated\n  # server-side. Fixes a misspelled account in place instead of delete + recreate.\n  # Ory Kratos signs users in by email, so a username change only updates the\n  # identity row; name/email changes also update the Kratos identity. The\n  # password is never disturbed. Returns the user.\n  updateUser(userId: String!, name: String!, email: String!, username: String!): User!\n\n  # Mark one of the acting user's notifications read.\n  markNotificationRead(id: ID!): Boolean!\n  # Mark all of the acting user's notifications read.\n  markAllNotificationsRead: Boolean!\n\n  # Authorizes an interactive SSH session against one of an ssh-key secret's\n  # attached targets: reveals the key (audited, RBAC-gated), hands session\n  # parameters to sshbroker, and returns a single-use WebSocket ticket.\n  # Starts on the target's default connection unless connectionId names one\n  # of the target's own connections. targetId picks which attached target to\n  # open: required when the secret has more than one, and defaults to the\n  # only one otherwise (#168). sshbroker independently checks targetId is\n  # actually attached before any auth is sent.\n  openSshSession(secretId: ID!, connectionId: ID, targetId: ID): SshSessionTicket!\n\n  # Service-account + API-token management. Site-admin-only:\n  # these are the human /graphql admin operations for the machine-auth surface\n  # served separately at /machine/graphql. The identity RPCs behind these do\n  # NOT self-authorize; the gateway enforces site-admin here.\n  createServiceAccount(name: String!, description: String!): ServiceAccount!\n  # Soft-disable (no delete); returns the updated service account.\n  disableServiceAccount(id: ID!): ServiceAccount!\n  # Mints a new API token for a service account. The plaintext token is\n  # returned exactly once, in this result, and is never re-fetchable.\n  # expiresAt is a Unix timestamp (seconds); omitted/0 means no expiry.\n  # scope is a space-separated list of groups, each a group ID or name slug\n  # (lowercase, whitespace runs -> \"-\", e.g. \"help-desk\"); every entry must\n  # resolve to exactly one group or the mint is rejected. It is stored as\n  # canonical group IDs, and it is the token's only RACI group grant.\n  mintApiToken(serviceAccountId: ID!, scope: String!, expiresAt: Int): MintApiTokenResult!\n  # Revokes a minted token; returns its updated metadata.\n  revokeApiToken(id: ID!): ApiToken!\n  # Links an OIDC/OAuth2 client (Ory Hydra client-credentials) to\n  # a service account: a JWT bearer whose verified issuer/sub then match\n  # resolves to this service account at /machine/graphql (via\n  # ResolveServiceAccountByOidc), alongside its existing opaque API token(s).\n  # The issuer is always the gateway's own configured Hydra issuer\n  # (HYDRA_ISSUER) — never caller-supplied. Site-admin-only.\n  # allowedGroups is required and bounds which RACI groups the client may\n  # ever hold: effective groups = JWT scope groups INTERSECT allowedGroups.\n  # It replaces any prior bound wholesale; [] links the client but grants no\n  # groups. Each entry is a group ID, exact name, or name slug and must\n  # resolve to exactly one group (else rejected); the bound is stored as group\n  # IDs. JWT scope tokens match a group by ID or slug (e.g. \"help-desk\").\n  linkOidcClient(serviceAccountId: ID!, oidcSubject: String!, allowedGroups: [String!]!): ServiceAccount!\n  # Removes a service account's OIDC client linkage; its opaque API-token\n  # path is unaffected. Site-admin-only.\n  unlinkOidcClient(serviceAccountId: ID!): ServiceAccount!\n}\n\n# Live push channel over WebSocket (graphql-ws). Every subscription is\n# authenticated from the session cookie on the socket's connection_init and is\n# RACI-scoped to the acting user exactly like the equivalent query.\ntype Subscription {\n  # Pushes the acting user's dashboard rollup: emits once immediately on\n  # subscribe, then whenever the readable-secrets stats change. Replaces the\n  # dashboard's poll while the socket is up. Scoped by the same GetSecretStats\n  # over the actor's readable secrets as the secretStats query.\n  secretStats: SecretStats!\n}\n";
